/**
 * `window.studioAgent`: the page half of the agent API (plan 40 §4). `studio-agent.ts` is the tool layer and never touches the browser;
 * this file installs it on the page, pairs a session with a key, and gives it eyes.
 *
 * The key is the whole trust story: a Studio session is bound to one pairing key, a new key cancels the old, and every call must carry
 * the current one. A call without a key, or with a stale one, is refused with the reason — the API is never open to whatever page shares
 * the tab. The key is generated by the Studio (`newPairingKey`) and shown to the person, who types it into their bridge.
 *
 * Eyes come in two grades, and the session is told which it has:
 *  - a live viewport (`setViewport`), which can draw the current view, a four-side turntable and one layer's mask;
 *  - the offscreen review renderer (`fourAngleShots`), which draws four angles of one generated asset at a time.
 * With neither attached, `capture` refuses with that reason rather than returning a blank image.
 */
import { fourAngleShots } from './four-angle';
import { REGISTRY } from './studio-data';
import { StudioSession, type Capture, type CaptureRequest } from './studio-agent';

/** What the page may attach so the agent can see: a live viewport, or one asset's four angles. */
export interface AgentEyes {
  /** The Studio viewport's own capture: the current view, the four sides, and one layer's mask. */
  readonly viewport?: (o: CaptureRequest) => Promise<string | null>;
  /** An asset id the offscreen review renderer can draw from four sides (used when no viewport is attached). */
  readonly asset?: () => string | null;
}

/** The calls the page exposes. Every one takes the pairing key first. */
export interface StudioAgentApi {
  readonly read: (key: string, id?: string) => unknown;
  readonly commands: (key: string) => unknown;
  readonly propose: (key: string, calls: unknown) => unknown;
  readonly changes: (key: string) => unknown;
  readonly accept: (key: string, id: string) => unknown;
  readonly reject: (key: string, id: string, why?: string) => unknown;
  readonly undo: (key: string) => unknown;
  readonly redo: (key: string) => unknown;
  readonly validateKit: (key: string, kit: unknown, preset: string, o?: unknown) => unknown;
  readonly materialCoverage: (key: string, o: unknown) => unknown;
  readonly capture: (key: string, o?: unknown) => Promise<unknown>;
  /** The session's own id and the key it is paired with (so a bridge can prove it is talking to the tab it thinks it is). */
  readonly hello: () => { readonly session: string; readonly paired: boolean; readonly eyes: 'viewport' | 'offscreen' | 'none' };
}

/**
 * A fresh pairing key: 8 hex groups, from the platform's crypto. The result is shown to the person once; it is not a password (it does
 * not leave the tab), it only proves that the bridge was given the key the Studio displayed.
 */
export function newPairingKey(random: (n: number) => Uint8Array = defaultRandom): string {
  const bytes = random(16);
  return [...bytes].map((b) => b.toString(16).padStart(2, '0')).join('');
}

function defaultRandom(n: number): Uint8Array {
  const out = new Uint8Array(n);
  const cryptoApi = (globalThis as { crypto?: { getRandomValues?: (a: Uint8Array) => Uint8Array } }).crypto;
  if (cryptoApi?.getRandomValues) {
    cryptoApi.getRandomValues(out);
    return out;
  }
  // a tab without Web Crypto still gets a key: the clock and Math.random are enough for a local pairing secret
  for (let i = 0; i < n; i += 1) out[i] = Math.floor(Math.random() * 256);
  return out;
}

const refuse = (why: string): { readonly ok: false; readonly why: string } => ({ ok: false, why });

/**
 * Installs `window.studioAgent` for one Studio session. Returns the API (so a test or the owner's own Playwright run can call it
 * directly) and a `disconnect` that unpairs and removes it. Calling twice replaces the first installation, which cancels the first key.
 */
export function installStudioAgent(o: {
  readonly key: string;
  readonly eyes?: AgentEyes;
  readonly doc?: ConstructorParameters<typeof StudioSession>[0]['doc'];
  /** The Studio's own history, so an accepted row lands in the document the person is looking at. */
  readonly history?: ConstructorParameters<typeof StudioSession>[0]['history'];
  readonly materials?: ConstructorParameters<typeof StudioSession>[0]['materials'];
  readonly target?: { studioAgent?: StudioAgentApi };
}): { readonly api: StudioAgentApi; readonly session: StudioSession; readonly disconnect: () => void } {
  let paired = true;
  const eyes = o.eyes ?? {};
  const capture: Capture | undefined =
    eyes.viewport || eyes.asset
      ? async (request) => {
          if (eyes.viewport) {
            const dataUrl = await eyes.viewport(request);
            return dataUrl ? { ok: true, dataUrl } : { ok: false, why: 'the viewport drew nothing (it may not be mounted yet)' };
          }
          const asset = eyes.asset?.();
          if (!asset) return { ok: false, why: 'no asset is selected, so there is nothing to draw from four sides' };
          const shots = await fourAngleShots(asset, request.rank === 0 ? 128 : 256);
          const dataUrl = shots.front;
          return dataUrl ? { ok: true, dataUrl } : { ok: false, why: `the review renderer could not draw '${asset}'` };
        }
      : undefined;

  const session = new StudioSession({
    registry: REGISTRY,
    doc: o.doc ?? emptyStudioDoc(),
    materials: o.materials ?? {},
    ...(o.history ? { history: o.history } : {}),
    ...(capture ? { capture } : {}),
  });

  const guard = (key: string): { readonly ok: false; readonly why: string } | null => {
    if (!paired) return refuse('this Studio session is unpaired (a new key replaced it, or the person disconnected)');
    if (key !== o.key) return refuse('the pairing key does not match this Studio session');
    return null;
  };

  const api: StudioAgentApi = {
    hello: () => ({ session: session.id, paired, eyes: eyes.viewport ? 'viewport' : eyes.asset ? 'offscreen' : 'none' }),
    read: (key, id) => guard(key) ?? session.read(id),
    commands: (key) => guard(key) ?? session.commands(),
    propose: (key, calls) => guard(key) ?? session.propose(asCalls(calls)),
    changes: (key) => guard(key) ?? session.changes(),
    accept: (key, id) => guard(key) ?? session.accept(id),
    reject: (key, id, why) => guard(key) ?? session.reject(id, why ?? ''),
    undo: (key) => guard(key) ?? session.undo(),
    redo: (key) => guard(key) ?? session.redo(),
    validateKit: (key, kit, preset, options) =>
      guard(key) ?? session.validateKit(kit as Parameters<StudioSession['validateKit']>[0], preset, (options ?? {}) as Parameters<StudioSession['validateKit']>[2]),
    materialCoverage: (key, request) => guard(key) ?? session.materialCoverage(request as Parameters<StudioSession['materialCoverage']>[0]),
    capture: async (key, request) => guard(key) ?? (await session.capture((request ?? {}) as Partial<CaptureRequest>)),
  };

  const target = o.target ?? (globalThis as { studioAgent?: StudioAgentApi });
  target.studioAgent = api;
  return {
    api,
    session,
    disconnect: () => {
      paired = false;
      if (target.studioAgent === api) delete target.studioAgent;
    },
  };
}

/** A Studio document with nothing in it (the page replaces it with the saved one). */
function emptyStudioDoc(): ConstructorParameters<typeof StudioSession>[0]['doc'] {
  return { v: 1, nextId: 1, roots: [], nodes: {} };
}

/** A proposal arrives over a bridge as JSON, so shape it before the pure layer sees it. */
function asCalls(input: unknown): Parameters<StudioSession['propose']>[0] {
  if (!Array.isArray(input)) return [];
  return input.map((call) => {
    const c = call as { label?: unknown; ops?: unknown; material?: unknown };
    return {
      ...(typeof c.label === 'string' ? { label: c.label } : {}),
      ...(Array.isArray(c.ops) ? { ops: c.ops as Parameters<StudioSession['propose']>[0][number]['ops'] } : {}),
      ...(c.material && typeof c.material === 'object' ? { material: c.material as Parameters<StudioSession['propose']>[0][number]['material'] } : {}),
    };
  });
}
